using System.Threading.RateLimiting;
using LinKit.Caching;
using LinKit.Data;
using LinKit.Outbox;
using LinKit.Resilience;
using LinKit.Sagas;
using LinKit.Tenancy;
using Microsoft.AspNetCore.RateLimiting;

WebApplicationBuilder builder = WebApplication.CreateBuilder(args);

// 1. Register every CQRS handler, pipeline behavior and the mediator generated by LinKit.Generator.
builder.Services.AddLinKitCqrs();

// 2. Register services decorated with [RegisterService] (for example IPricingService).
builder.Services.AddLinKitDependency();

// 3. Register caching: in-memory by default, or hybrid (L1 memory + L2 Redis) when configured.
var cacheProvider = builder.Configuration.GetValue<string>("Cache:Provider") ?? "Memory";

if (string.Equals(cacheProvider, "Redis", StringComparison.OrdinalIgnoreCase))
{
    var redisConfig = builder.Configuration.GetSection("Redis");
    var redisOptions = new LinKitRedisOptions
    {
        Enabled = redisConfig.GetValue("Enabled", true),
        Host = redisConfig.GetValue("Host", "localhost")!,
        Port = redisConfig.GetValue("Port", 6379),
        Password = redisConfig.GetValue<string?>("Password"),
        Database = redisConfig.GetValue("Database", 0),
        DefaultTtl = TimeSpan.FromMinutes(redisConfig.GetValue("DefaultTtlMinutes", 30)),
    };

    builder.Services.AddLinKitRedisCaching(redisOptions);
}
else
{
    // Default: in-memory provider.
    builder.Services.AddLinKitCaching();
}

// Register the JSON context used for serialization (Native AOT safe and required by Redis caching).
LinKit.Core.Messaging.LinKitMessageJson.AddContext(MonolithSample.MonolithDataJsonContext.Default);

builder.Services.AddLinKitResilience();

// 4. Register tenancy (multi-tenancy through AsyncLocal), the outbox and sagas.
builder.Services.AddLinKitTenancy();
builder.Services.AddLinKitOutbox();
builder.Services.AddLinKitSagas<MonolithSample.Modules.Ordering.Commands.OrderSagaState>(
    // This sample only wires an in-memory saga repository. A real deployment must register a durable
    // ISagaRepository before calling AddLinKitSagas, otherwise resolution throws when the environment is Production.
    options => options.AllowInMemoryInProduction = true
);

// 5. Register LinKit.Data: a zero-reflection ORM with automatic schema synchronization.
builder.Services.AddLinKitData(options =>
{
    // Never hard-code credentials. Provide "ConnectionStrings:DefaultConnection" through appsettings,
    // user-secrets or environment variables.
    var connectionString =
        builder.Configuration.GetConnectionString("DefaultConnection")
        ?? "Server=localhost,1433;Database=MonolithSampleDb;Integrated Security=False;TrustServerCertificate=True;";

    options.UseConnection(
        DatabaseDialect.SqlServer,
        () => new Microsoft.Data.SqlClient.SqlConnection(connectionString)
    );

    // Creates the database on the server when it does not exist yet.
    options.EnsureDatabaseCreated = true;

    // Use when the login above lacks permission to create databases; it must point at a privileged account.
    // options.AdminConnectionString = builder.Configuration["Data:AdminConnectionString"];

    // options.ConfigureUserProvisioning(user =>
    // {
    //     user.Enabled = true;
    //     user.Username = builder.Configuration["Data:AppUserName"]!;
    //     user.Password = builder.Configuration["Data:AppUserPassword"]!;
    //     user.Roles = ["db_owner"];
    // });

    // Create missing tables and columns when the model changes.
    options.AutoSyncSchema = true;

    // Run the versioned data migrations registered with [Migration].
    options.RunMigrations = true;

    // Fully Native AOT and trimming safe JSON.
    options.UseJsonSerializerContext(MonolithSample.MonolithDataJsonContext.Default);
});

// 6. Register the background job manager, which runs jobs described by a JSON configuration file.
builder.AddBackgroundJobs("BackgroundJobsConfig.json");

// 7. Rate limiting and CORS policies consumed by [ApiEndpoint] declarations.
builder.Services.AddRateLimiter(options =>
{
    options.AddFixedWindowLimiter(
        "FixedWindow",
        opt =>
        {
            opt.PermitLimit = 100;
            opt.Window = TimeSpan.FromMinutes(1);
            opt.QueueLimit = 10;
            opt.QueueProcessingOrder = QueueProcessingOrder.OldestFirst;
        }
    );
});

builder.Services.AddCors(options =>
{
    options.AddPolicy("AllowAll", p => p.AllowAnyOrigin().AllowAnyMethod().AllowAnyHeader());
});

// 8. Swagger / OpenAPI document and UI.
builder.Services.AddEndpointsApiExplorer();
builder.Services.AddSwaggerGen();

WebApplication app = builder.Build();

app.UseSwagger();
app.UseSwaggerUI(c =>
{
    c.SwaggerEndpoint("/swagger/v1/swagger.json", "LinKit Monolith API v1");
});

// Redirect the root path to the Swagger UI so the sample is usable as soon as it starts.
app.MapGet("/", () => Results.Redirect("/swagger")).ExcludeFromDescription();

app.UseCors("AllowAll");
app.UseRateLimiter();

// 9. Map every [ApiEndpoint] together with its route, authorization, policy and OpenAPI metadata.
app.MapGeneratedEndpoints();

app.Run();
